fonction private.envoyer_alertes():
CREATE OR REPLACE FUNCTION private.envoyer_alertes()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cle text;
  v_nom_secret text := (select valeur from private.reglages where cle = 'alertes_secret_resend');
  v_expediteur text := (select valeur from private.reglages where cle = 'alertes_expediteur');
  v_destinataire text := (select valeur from private.reglages where cle = 'alertes_destinataire');
  v_exp_avis text := coalesce((select valeur from private.reglages where cle = 'avis_expediteur'),
                              (select valeur from private.reglages where cle = 'alertes_expediteur'));
  v_espace text := coalesce((select valeur from private.reglages where cle = 'espace_url'), 'https://app.omegaai.fr/espace');
  v_dest text[];
  r record;
  n integer := 0;
begin
  select s.decrypted_secret into v_cle from vault.decrypted_secrets s where s.name = v_nom_secret limit 1;
  if v_cle is null then
    return 0;
  end if;

  if v_destinataire is not null then
    for r in
      select a.id, a.titre, a.detail, a.cree_le
      from public.alertes a
      where a.envoyee_le is null and a.niveau = 'critique' and a.acquittee_le is null and a.interne
      order by a.cree_le
      limit 20
    loop
      perform net.http_post(
        url := 'https://api.resend.com/emails',
        headers := jsonb_build_object('Authorization', 'Bearer ' || v_cle, 'Content-Type', 'application/json'),
        body := jsonb_build_object(
          'from', v_expediteur,
          'to', jsonb_build_array(v_destinataire),
          'subject', '[Omega] ' || r.titre,
          'text', r.titre || E'\n\nLevée le ' || to_char(r.cree_le at time zone 'America/Guadeloupe', 'DD/MM/YYYY à HH24:MI')
                  || ' (heure de Guadeloupe).' || E'\n\nDétail : ' || r.detail::text
                  || E'\n\nCet e-mail part de la base Omega (chien de garde).'));
      update public.alertes set envoyee_le = now() where id = r.id;
      n := n + 1;
    end loop;
  end if;

  for r in
    select a.id, a.client_id, a.niveau, a.source, a.titre, a.destinataire_id
    from public.alertes a
    where a.envoyee_le is null and a.acquittee_le is null and not a.interne
      and a.niveau in ('attention', 'critique') and a.cree_le > now() - interval '7 days'
    order by a.cree_le
    limit 20
  loop
    v_dest := null;
    if r.destinataire_id is not null then
      select array_agg(u.email) into v_dest from auth.users u where u.id = r.destinataire_id and u.email is not null;
    end if;

    if v_dest is null then
      select array_agg(distinct u.email order by u.email) into v_dest
      from (
        select d.user_id from public.destinataires_avis d
        where d.client_id = r.client_id and d.user_id is not null
          and private.rang_niveau(r.niveau) >= private.rang_niveau(d.niveau_min)
          and (d.sources is null or r.source = any (d.sources))
        union
        select m.user_id from public.destinataires_avis d
        join public.equipes_membres m on m.equipe_id = d.equipe_id
        where d.client_id = r.client_id and d.equipe_id is not null
          and private.rang_niveau(r.niveau) >= private.rang_niveau(d.niveau_min)
          and (d.sources is null or r.source = any (d.sources))
      ) x
      join auth.users u on u.id = x.user_id
      where u.email is not null;
    end if;

    if v_dest is null and r.niveau = 'critique'
       and not exists (select 1 from public.destinataires_avis d where d.client_id = r.client_id) then
      select array_agg(distinct u.email order by u.email) into v_dest
      from public.comptes c join auth.users u on u.id = c.user_id
      where c.client_id = r.client_id and c.role = 'gerant' and u.email is not null;
    end if;

    continue when v_dest is null or cardinality(v_dest) = 0;

    perform net.http_post(
      url := 'https://api.resend.com/emails',
      headers := jsonb_build_object('Authorization', 'Bearer ' || v_cle, 'Content-Type', 'application/json'),
      body := jsonb_build_object(
        'from', v_exp_avis,
        'to', to_jsonb(v_dest),
        'subject', r.titre,
        'text', r.titre || E'\n\nLe détail vous attend dans votre espace : ' || v_espace
                || E'\n\nVous recevez cet avis parce que votre organisation vous a désigné pour le recevoir.'
                || E'\n\n— Omega'));
    update public.alertes set envoyee_le = now() where id = r.id;
    n := n + 1;
  end loop;
  return n;
end $function$

fonction private.exporter_client(uuid,uu:
CREATE OR REPLACE FUNCTION private.exporter_client(p_client uuid, p_demandeur uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r record;
  v_tables jsonb := '{}'::jsonb;
  v_lignes jsonb;
  v_empreinte text;
begin
  if not exists (select 1 from public.clients where id = p_client) then
    raise exception 'Organisation introuvable.' using errcode = 'P0002';
  end if;

  for r in select t.nom from private.tables_locataires t order by t.nom loop
    execute format(
      'select coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text), ''[]''::jsonb) from public.%I x where x.client_id = $1',
      r.nom)
    into v_lignes using p_client;
    v_tables := v_tables || jsonb_build_object(r.nom, v_lignes);
  end loop;

  v_tables := v_tables || jsonb_build_object('clients', (
    select coalesce(jsonb_agg(
      (to_jsonb(c) - 'stripe_customer_id') || jsonb_build_object('config', (
        select coalesce(jsonb_object_agg(e.cle, e.valeur), '{}'::jsonb)
        from jsonb_each(c.config) as e(cle, valeur)
        where e.cle !~* '(token|secret|jeton|password|mot_de_passe|cle_api|api_key)'))), '[]'::jsonb)
    from public.clients c where c.id = p_client));

  v_tables := v_tables || jsonb_build_object('fichiers', (
    select coalesce(jsonb_agg(jsonb_build_object('bucket', f.bucket, 'nom', f.nom, 'octets', f.octets,
                                                 'empreinte', f.empreinte, 'cree_le', f.cree_le)
                              order by f.bucket, f.nom), '[]'::jsonb)
    from private.fichiers_de(p_client) f));

  v_empreinte := encode(sha256(convert_to(v_tables::text, 'UTF8')), 'hex');

  perform private.journaliser(p_client, 'donnees.export', 'clients', p_client::text,
    jsonb_build_object('empreinte_sha256', v_empreinte, 'demandeur', p_demandeur));

  return jsonb_build_object(
    'organisation', p_client,
    'genere_le', to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    'empreinte_sha256', v_empreinte,
    'tables', v_tables);
end $function$

fonction private.filed_decider_facture(p:
CREATE OR REPLACE FUNCTION private.filed_decider_facture(p_d demandes_validation, p_decideur uuid, p_commentaire text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_f public.filed_factures; v_v public.filed_validations; v_decideurs uuid[]; v_a public.filed_archives; r record;
begin
  select * into v_f from public.filed_factures where client_id = p_d.client_id and id::text = p_d.objet_id for update;
  if not found then return 'facture_effacee'; end if;
  select * into v_v from public.filed_validations where demande_id = p_d.id;

  if p_d.statut = 'approuvee' and p_d.politique_id is not null then
    update public.demandes_validation set statut = 'echec_execution', motif_echec = 'Une facture n''est jamais validée d''office par un accord permanent.' where id = p_d.id;
    update public.filed_validations set issue = 'refus_accord', decide_le = now() where demande_id = p_d.id;
    return 'refuse_accord';
  end if;

  if v_f.statut <> 'a_valider' or v_f.version <> coalesce((p_d.payload->>'version')::integer, v_f.version) then
    if p_d.statut = 'approuvee' then update public.demandes_validation set statut = 'executee' where id = p_d.id; end if;
    update public.filed_validations set issue = 'perimee', decide_le = now() where demande_id = p_d.id;
    perform private.filed_historiser(v_f.client_id, v_f.document_id, 'filed_facture', v_f.id::text, 'decision_perimee',
      format('Décision (%s) arrivée après un changement de la facture (statut %s, version %s) : sans effet.', p_d.statut, v_f.statut, v_f.version),
      jsonb_build_object('demande', p_d.id));
    return 'perimee';
  end if;

  if p_d.statut = 'approuvee' then
    -- Celui qui saisit et celui qui approuve ne sont pas la même personne : le socle le refuse à l'insertion
    -- de l'approbation (preparer_approbation lit payload->'saisi_par', posé par filed_deposer_validation).
    select coalesce(array_agg(distinct coalesce(a.au_nom_de, a.user_id)), '{}') into v_decideurs from public.approbations a where a.demande_id = p_d.id and a.decision = 'approuve';
    update public.filed_factures set statut = 'validee', maj_le = now() where id = v_f.id;
    v_f.statut := 'validee';
    for r in select a.user_id, a.au_nom_de, a.commentaire from public.approbations a where a.demande_id = p_d.id and nullif(btrim(a.commentaire), '') is not null loop
      insert into public.filed_factures_annexes (client_id, facture_id, document_id, nature, texte, auteur_id, demande_id)
      values (v_f.client_id, v_f.id, v_f.document_id, 'approbation', left(r.commentaire, 2000), r.user_id, p_d.id);
    end loop;
    v_a := private.filed_archiver(v_f.id);
    perform private.filed_historiser(v_f.client_id, v_f.document_id, 'filed_facture', v_f.id::text, 'validee',
      format('Validée par %s personne(s)%s : classée, empreinte au journal (ligne %s).', cardinality(v_decideurs),
             case when v_v.niveau = 2 then ' (direction)' else '' end, v_a.journal_id),
      jsonb_build_object('demande', p_d.id, 'decideurs', to_jsonb(v_decideurs), 'archive', v_a.id, 'journal', v_a.journal_id, 'version', v_f.version));
    perform private.filed_journaliser(v_f.client_id, 'filed.validation', 'filed_facture', v_f.id::text,
      jsonb_build_object('demande', p_d.id, 'decision', 'approuvee', 'niveau', v_v.niveau, 'decideurs', to_jsonb(v_decideurs), 'version', v_f.version, 'archive', v_a.id), v_f.entite_id);
    update public.filed_validations set issue = 'approuvee', decide_le = now() where demande_id = p_d.id;
    update public.demandes_validation set statut = 'executee' where id = p_d.id;
    if not exists (select 1 from public.filed_imputations i where i.facture_id = v_f.id and i.statut in ('proposee', 'validee')) then
      perform private.filed_proposer_imputation(v_f.id, 'apprise');
    end if;
    return 'facture_validee';

  elsif p_d.statut = 'rejetee' then
    update public.filed_factures set statut = 'refusee', maj_le = now() where id = v_f.id;
    insert into public.filed_factures_annexes (client_id, facture_id, document_id, nature, texte, auteur_id, demande_id)
    values (v_f.client_id, v_f.id, v_f.document_id, 'motif_refus', left(coalesce(nullif(btrim(p_commentaire), ''), 'Refusée sans motif écrit.'), 2000), p_decideur, p_d.id);
    perform private.filed_historiser(v_f.client_id, v_f.document_id, 'filed_facture', v_f.id::text, 'refusee',
      'Refusée par une personne' || coalesce(' : ' || left(btrim(p_commentaire), 300), '.'), jsonb_build_object('demande', p_d.id, 'par', p_decideur));
    perform private.filed_journaliser(v_f.client_id, 'filed.validation', 'filed_facture', v_f.id::text,
      jsonb_build_object('demande', p_d.id, 'decision', 'rejetee', 'version', v_f.version), v_f.entite_id);
    perform private.lever_alerte_module(v_f.client_id, 'filed', 'attention',
      left(format('Facture %s refusée%s', coalesce(v_f.numero, '?'), coalesce(' : ' || left(btrim(p_commentaire), 120), '.')), 200),
      jsonb_build_object('facture', v_f.id, 'demande', p_d.id), 'facture_refusee:' || v_f.id::text, true, null);
    update public.filed_validations set issue = 'rejetee', decide_le = now() where demande_id = p_d.id;
    update public.filed_charges_attendues set statut = 'attendue', facture_id = null, recue_le = null where facture_id = v_f.id and statut = 'recue';
    return 'facture_refusee';
  end if;

  update public.filed_validations set issue = 'expiree', decide_le = now() where demande_id = p_d.id;
  return 'expiree';
end $function$

fonction private.filed_deposer_validatio:
CREATE OR REPLACE FUNCTION private.filed_deposer_validation(p_facture uuid, p_niveau integer DEFAULT 1, p_suffixe text DEFAULT ''::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_f public.filed_factures; v_doc public.filed_documents; v_four text; v_centre uuid; v_centre_code text; v_circuit public.filed_circuits;
  v_type text; v_cle text; v_demande uuid; v_montant numeric; v_regle uuid; v_resume text; v_d public.demandes_validation;
begin
  select * into v_f from public.filed_factures where id = p_facture;
  if not found or v_f.statut <> 'a_valider' then return null; end if;
  select * into v_doc from public.filed_documents where id = v_f.document_id;
  select f.nom into v_four from public.filed_fournisseurs f where f.id = v_f.fournisseur_id;
  v_centre := private.filed_centre_de(v_f.id);
  select k.code into v_centre_code from public.filed_centres_cout k where k.id = v_centre;
  v_montant := abs(coalesce(v_f.montant_ttc, 0));
  v_circuit := private.filed_circuit_pour(v_f.client_id, v_f.entite_id, v_centre, v_montant, p_niveau);
  v_type := private.filed_type_action_facture(v_f.client_id, v_centre, p_niveau);

  if p_niveau = 2 and v_circuit.id is null then
    insert into public.regles_validation (client_id, entite_id, module, montant_min, montant_max, approbations_requises, roles_autorises, actif, type_action, equipe_id)
    values (v_f.client_id, null, 'filed', 0, null, 1, array['gerant', 'admin'], true, v_type, null) returning id into v_regle;
    insert into public.filed_circuits (client_id, entite_id, centre_id, montant_min, niveau, approbations_requises, roles_autorises, regle_id)
    values (v_f.client_id, null, null, 0, 2, 1, array['gerant', 'admin'], v_regle) returning * into v_circuit;
  end if;

  v_cle := 'filed:facture:' || v_f.id::text || ':v' || v_f.version::text || case when p_niveau = 2 then ':n2' else '' end || coalesce(p_suffixe, '')
           || private.filed_suffixe_caduque(v_f.id);   -- a4_75 : après une validation caduque, une nouvelle demande
  update public.demandes_validation set statut = 'annulee'
   where client_id = v_f.client_id and module = 'filed' and objet_type = 'filed_facture' and objet_id = v_f.id::text
     and type_action like 'filed.valider_facture%' and statut = 'en_attente' and cle_idempotence <> v_cle;
  update public.filed_validations v set issue = 'annulee', decide_le = now()
   from public.demandes_validation d where d.id = v.demande_id and v.facture_id = v_f.id and v.issue is null and d.statut = 'annulee';

  v_resume := left(format('Valider %s %s de %s : %s TTC%s%s%s',
    case when v_f.nature = 'avoir' then 'l''avoir' else 'la facture' end, coalesce(v_f.numero, '(sans numéro)'), coalesce(v_four, 'fournisseur inconnu'),
    private.filed_montant_texte(coalesce(v_f.montant_ttc, 0)),
    coalesce(', centre ' || v_centre_code, ''),
    case when p_niveau = 2 then ' — remontée à la direction' else '' end,
    case when v_f.nb_attention > 0 then format(' (%s point(s) d''attention)', v_f.nb_attention) else '' end), 500);

  v_demande := private.filed_deposer_demande(v_f.client_id, v_f.entite_id, v_type, 'filed_facture', v_f.id::text, v_resume, v_montant,
    jsonb_build_object('facture', v_f.id, 'document', v_f.document_id, 'reference', v_doc.reference, 'version', v_f.version, 'niveau', p_niveau,
                       'centre', v_centre, 'montant_ttc', v_f.montant_ttc, 'fournisseur', v_f.fournisseur_id, 'anomalies', to_jsonb(v_f.anomalies),
                       'saisi_par', to_jsonb(private.filed_saisisseurs_tenus(v_f.id))   /* a4_76 : un gérant sous le seuil approuve seul */, 'circuit', v_circuit.id),
    v_cle);
  if v_demande is null then return null; end if;
  select * into v_d from public.demandes_validation where id = v_demande;

  insert into public.filed_validations (client_id, facture_id, document_id, demande_id, version, niveau, type_action, circuit_id)
  values (v_f.client_id, v_f.id, v_f.document_id, v_demande, v_f.version, p_niveau, v_type, v_circuit.id)
  on conflict (demande_id) do nothing;
  if found then
    perform private.filed_historiser(v_f.client_id, v_f.document_id, 'filed_facture', v_f.id::text, 'validation_demandee',
      format('Validation demandée (niveau %s, %s approbation(s) : %s%s).', p_niveau, v_d.approbations_requises, array_to_string(v_d.roles_autorises, ', '),
             coalesce(', équipe ' || (select e.nom from public.equipes e where e.id = v_d.equipe_id), '')),
      jsonb_build_object('demande', v_demande, 'type_action', v_type, 'niveau', p_niveau, 'circuit', v_circuit.id, 'approbations_requises', v_d.approbations_requises));
  end if;
  return v_demande;
end $function$

fonction private.filed_regler_circuit(uu:
CREATE OR REPLACE FUNCTION private.filed_regler_circuit(p_client uuid, p_entite uuid, p_centre uuid, p_montant_min numeric, p_montant_max numeric, p_approbations_requises integer, p_roles text[], p_equipe uuid DEFAULT NULL::uuid, p_niveau integer DEFAULT 1, p_delai_relance_jours integer DEFAULT 3, p_delai_remontee_jours integer DEFAULT 7)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid; v_c public.filed_circuits; v_regle uuid; v_type text; v_roles text[] := coalesce(p_roles, array['gerant', 'admin', 'valideur']);
begin
  v_uid := private.filed_exiger_acteur(p_client, array['gerant', 'admin'], p_entite);
  if p_centre is not null and not exists (select 1 from public.filed_centres_cout k where k.id = p_centre and k.client_id = p_client and k.actif) then
    raise exception 'Centre de coût introuvable ou retiré.' using errcode = '22023';
  end if;
  if p_equipe is not null and not exists (select 1 from public.equipes e where e.id = p_equipe and e.client_id = p_client) then
    raise exception 'Équipe introuvable.' using errcode = '22023';
  end if;
  if not (v_roles <@ array['gerant', 'admin', 'valideur']) or cardinality(v_roles) = 0 then
    raise exception 'Les rôles d''un circuit sont gerant, admin ou valideur.' using errcode = '22023';
  end if;
  if coalesce(p_niveau, 1) not in (1, 2) then raise exception 'Le niveau est 1 (approbation) ou 2 (direction).' using errcode = '22023'; end if;

  select * into v_c from public.filed_circuits c
   where c.client_id = p_client and c.entite_id is not distinct from p_entite and c.centre_id is not distinct from p_centre
     and c.niveau = coalesce(p_niveau, 1) and c.montant_min = coalesce(p_montant_min, 0) and c.actif;
  if found then
    update public.filed_circuits set montant_max = p_montant_max, approbations_requises = coalesce(p_approbations_requises, 1), roles_autorises = v_roles,
      equipe_id = p_equipe, delai_relance_jours = coalesce(p_delai_relance_jours, 3), delai_remontee_jours = coalesce(p_delai_remontee_jours, 7)
     where id = v_c.id returning * into v_c;
  else
    insert into public.filed_circuits (client_id, entite_id, centre_id, montant_min, montant_max, niveau, approbations_requises, roles_autorises, equipe_id, delai_relance_jours, delai_remontee_jours, cree_par)
    values (p_client, p_entite, p_centre, coalesce(p_montant_min, 0), p_montant_max, coalesce(p_niveau, 1), coalesce(p_approbations_requises, 1), v_roles, p_equipe, coalesce(p_delai_relance_jours, 3), coalesce(p_delai_remontee_jours, 7), v_uid)
    returning * into v_c;
  end if;

  v_type := private.filed_type_action_facture(p_client, p_centre, coalesce(p_niveau, 1));
  if v_c.regle_id is not null then
    update public.regles_validation set entite_id = p_entite, montant_min = coalesce(p_montant_min, 0), montant_max = p_montant_max,
      approbations_requises = coalesce(p_approbations_requises, 1), roles_autorises = v_roles, equipe_id = p_equipe, type_action = v_type, actif = true
     where id = v_c.regle_id;
    v_regle := v_c.regle_id;
  else
    insert into public.regles_validation (client_id, entite_id, module, montant_min, montant_max, approbations_requises, roles_autorises, actif, type_action, equipe_id)
    values (p_client, p_entite, 'filed', coalesce(p_montant_min, 0), p_montant_max, coalesce(p_approbations_requises, 1), v_roles, true, v_type, p_equipe)
    returning id into v_regle;
    update public.filed_circuits set regle_id = v_regle where id = v_c.id;
  end if;
  perform private.filed_journaliser(p_client, 'filed.circuit', 'filed_circuit', v_c.id::text,
    jsonb_build_object('type_action', v_type, 'niveau', coalesce(p_niveau, 1), 'montant_min', coalesce(p_montant_min, 0), 'montant_max', p_montant_max,
                       'approbations_requises', coalesce(p_approbations_requises, 1), 'roles', to_jsonb(v_roles), 'equipe', p_equipe, 'centre', p_centre, 'regle', v_regle), p_entite);
  return v_c.id;
end $function$

fonction private.lorani_alerter_rappel(p:
CREATE OR REPLACE FUNCTION private.lorani_alerter_rappel(p lorani_permis, p_projet lorani_projets, p_nature text, p_rappel integer, p_echeance date, p_calcul jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_titre text;
  v_niveau text;
  v_quand text := case p_rappel when 0 then 'aujourd''hui' when 1 then 'demain' else format('dans %s jours', p_rappel) end;
  v_cle text := format('permis:%s:%s:rappel:%s', p.id, p_nature, p_rappel);
  v_resp uuid := private.lorani_chef_de_projet(p.client_id, p.projet_id);
  v_alerte uuid;
  v_corps text;
  v_envoi uuid;
begin
  if p_nature = 'pieces' and p.date_pieces_fournies is null then
    v_niveau := case when p_rappel >= 10 then 'attention' else 'critique' end;
    v_titre := format('%s : pièces manquantes à faire recevoir par la mairie au plus tard le %s (%s), sinon rejet tacite.',
      private.lorani_titre_permis(p, p_projet), to_char(p_echeance, 'DD/MM/YYYY'), v_quand);
    v_corps := format(E'Bonjour,\n\nLa mairie a réclamé des pièces pour le %s (dossier %s). Elles doivent lui être parvenues au plus tard le %s, c''est-à-dire %s. Passé ce jour, la demande est tacitement rejetée (code de l''urbanisme, art. R*423-39, b).\n\nPièces réclamées : %s.\n\nUne fois les pièces reçues par la mairie, saisissez la date de leur réception dans Omega : l''instruction en repart.\n\nOmega — Lorani',
      private.lorani_titre_permis(p, p_projet), coalesce(p.numero, 'sans numéro'), to_char(p_echeance, 'DD/MM/YYYY'), v_quand,
      coalesce((select string_agg(x ->> 'code', ', ') from jsonb_array_elements(p.pieces_demandees) x), 'voir la lettre de la mairie'));
  elsif p_nature = 'instruction' and p.decision is null then
    v_niveau := 'info';
    v_titre := format('%s : décision de la mairie attendue au plus tard le %s (%s) ; sans réponse, %s.',
      private.lorani_titre_permis(p, p_projet), to_char(p_echeance, 'DD/MM/YYYY'), v_quand,
      coalesce(p_calcul #>> '{regime,effet_silence}', 'permis tacite'));
    v_corps := format(E'Bonjour,\n\nLe délai d''instruction du %s (dossier %s) s''achève le %s, %s. Sans décision notifiée à cette date, le silence de la mairie vaut %s.\n\nSi un arrêté ou une lettre arrive d''ici là, déposez-le dans Omega : la date sera lue et le calendrier recalculé.\n\nOmega — Lorani',
      private.lorani_titre_permis(p, p_projet), coalesce(p.numero, 'sans numéro'), to_char(p_echeance, 'DD/MM/YYYY'), v_quand,
      coalesce(p_calcul #>> '{regime,effet_silence}', 'permis tacite'));
  elsif p_nature = 'affichage' and p.date_affichage is null then
    v_niveau := 'attention';
    v_titre := format('%s : affichage sur le terrain non saisi quinze jours après la décision. Tant qu''il n''est pas fait, le recours des tiers ne court pas.',
      private.lorani_titre_permis(p, p_projet));
    v_corps := format(E'Bonjour,\n\nLe %s (dossier %s) est accordé depuis le %s et son affichage sur le terrain n''est pas saisi dans Omega. Tant que le panneau n''est pas en place, le délai de recours des tiers ne court pas (code de l''urbanisme, art. R*600-2) et le permis ne se purge pas.\n\nAffichez le permis, faites-le constater, puis saisissez le premier jour d''affichage dans Omega.\n\nOmega — Lorani',
      private.lorani_titre_permis(p, p_projet), coalesce(p.numero, 'sans numéro'), to_char(p.date_decision, 'DD/MM/YYYY'));
  else
    return null;
  end if;

  v_alerte := private.lever_alerte_module(p.client_id, 'lorani', v_niveau, left(v_titre, 200),
    jsonb_build_object('projet', p.projet_id, 'permis', p.id, 'nature', p_nature, 'echeance', p_echeance,
                       'rappel', p_rappel, 'lien', private.lorani_lien_permis(p.id)),
    v_cle, true, v_resp);

  -- Le rappel part au chef de projet, par courriel, le jour même. Il n'est pas un travail de l'alerte : s'il échoue, l'alerte reste.
  if v_resp is not null then
    begin
      v_envoi := private.preparer_envoi(
        p.client_id, 'lorani', 'lorani_projet', p.projet_id::text, 'email',
        jsonb_build_object('membre', v_resp),
        null, '{}'::jsonb,
        left('Omega — ' || v_titre, 300),
        v_corps || E'\n\nOuvrir le dossier : ' || regexp_replace(coalesce(public.lire_parametre('espace_url'), 'https://app.omegaai.fr/espace'), '/espace2?/?$', '') || private.lorani_lien_permis(p.id),
        null, 'lorani:' || v_cle, p.entite_id, true, false,
        greatest(p_echeance::timestamptz, now() + interval '1 hour'), '{}'::jsonb);
      if v_alerte is not null and v_envoi is not null then
        update public.alertes set detail = detail || jsonb_build_object('envoi', v_envoi) where id = v_alerte;
      end if;
    exception when others then
      perform private.lever_alerte(p.client_id, true, 'attention', 'lorani',
        left(format('Rappel du permis non préparé en envoi : %s', sqlerrm), 200),
        jsonb_build_object('permis', p.id, 'nature', p_nature, 'rappel', p_rappel, 'erreur', left(sqlstate || ' ' || sqlerrm, 300)),
        'lorani:envoi_rappel:' || p.id::text || ':' || p_nature);
    end;
  end if;
  return v_alerte;
end $function$

fonction private.lorani_chantier_rappele:
CREATE OR REPLACE FUNCTION private.lorani_chantier_rappeler(t travaux)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r public.lorani_reserves;
  pt public.lorani_points;
  pr public.lorani_projets;
  v_delai uuid := (t.charge ->> 'delai')::uuid;
  v_rappel integer := (t.charge ->> 'rappel')::integer;
  v_depasse boolean := t.genre = 'lorani.chantier.depasse';
  v_ouvertes integer;
  v_detail text;
  v_lot text;
  v_qui text;
begin
  select * into pt from public.lorani_points where delai_id = v_delai;
  if found then
    if pt.statut <> 'ouvert' then
      return jsonb_build_object('ignore', 'point répondu ou soldé', 'point', pt.id);
    end if;
    select * into pr from public.lorani_projets where id = pt.projet_id;
    v_qui := coalesce((select organisme from public.lorani_intervenants where id = pt.intervenant_id), 'l''équipe');
    perform private.lever_alerte_module(pt.client_id, 'lorani', 'attention',
      left(format('« %s » : %s (%s) %s — %s', left(pr.nom, 40),
                  case pt.nature when 'question' then 'question sans réponse' else 'action non faite' end, left(v_qui, 40),
                  case when v_depasse then 'attendue le ' || to_char(pt.echeance, 'DD/MM/YYYY')
                       else 'attendue ' || case coalesce(v_rappel, 0) when 0 then 'aujourd''hui' when 1 then 'demain' else 'dans ' || v_rappel || ' jours' end end,
                  pt.texte), 200),
      jsonb_build_object('projet', pt.projet_id, 'point', pt.id, 'lien', private.lorani_lien_projet(pt.projet_id)),
      case when v_depasse then format('point:%s:retard', pt.id) else format('point:%s:rappel:%s', pt.id, coalesce(v_rappel, 0)) end,
      true, private.lorani_chef_de_projet(pt.client_id, pt.projet_id));
    return jsonb_build_object('point', pt.id, 'genre', t.genre, 'rappel', v_rappel);
  end if;

  select * into r from public.lorani_reserves where delai_id = v_delai;
  if found then
    if r.statut <> 'ouverte' then
      return jsonb_build_object('ignore', 'réserve levée ou contestée', 'reserve', r.id);
    end if;
    select * into pr from public.lorani_projets where id = r.projet_id;
    select l.numero into v_lot from public.lorani_lots l where l.id = r.lot_id;
    perform private.lever_alerte_module(r.client_id, 'lorani', 'attention',
      left(case when v_depasse
        then format('« %s » : réserve n° %s%s non levée au %s — %s', left(pr.nom, 40), r.numero, coalesce(' (lot ' || v_lot || ')', ''), to_char(r.lever_avant, 'DD/MM/YYYY'), r.intitule)
        else format('« %s » : réserve n° %s%s à lever avant le %s (%s) — %s', left(pr.nom, 40), r.numero, coalesce(' (lot ' || v_lot || ')', ''), to_char(r.lever_avant, 'DD/MM/YYYY'),
                    case coalesce(v_rappel, 0) when 0 then 'aujourd''hui' when 1 then 'demain' else 'dans ' || v_rappel || ' jours' end, r.intitule) end, 200),
      jsonb_build_object('projet', r.projet_id, 'reserve', r.id, 'lien', private.lorani_lien_projet(r.projet_id)),
      case when v_depasse then format('reserve:%s:retard', r.id) else format('reserve:%s:rappel:%s', r.id, coalesce(v_rappel, 0)) end,
      true, private.lorani_chef_de_projet(r.client_id, r.projet_id));
    return jsonb_build_object('reserve', r.id, 'genre', t.genre, 'rappel', v_rappel);
  end if;

  select * into pr from public.lorani_projets where gpa_delai_id = v_delai;
  if not found then
    return jsonb_build_object('ignore', 'délai hors du chantier');
  end if;
  select string_agg(case when x.numero is null then format('sans lot : %s', x.n) else format('lot %s : %s', x.numero, x.n) end, ', ' order by x.numero nulls last)
    into v_detail
  from (select l.numero, count(*) as n from public.lorani_reserves rr left join public.lorani_lots l on l.id = rr.lot_id
        where rr.projet_id = pr.id and rr.statut = 'ouverte' group by l.numero) x;
  select coalesce(sum(n), 0) into v_ouvertes from (select count(*) as n from public.lorani_reserves rr where rr.projet_id = pr.id and rr.statut = 'ouverte') y;
  perform private.lever_alerte_module(pr.client_id, 'lorani', case when v_ouvertes > 0 then 'attention' else 'info' end,
    left(format('« %s » : %s le %s ; %s', left(pr.nom, 40),
                case when v_depasse then 'la garantie de parfait achèvement a pris fin' else 'fin de la garantie de parfait achèvement' end,
                to_char((pr.reception_le + interval '1 year')::date, 'DD/MM/YYYY'),
                case when v_ouvertes = 0 then 'toutes les réserves sont levées, la retenue de garantie peut être libérée.'
                     else format('%s réserve%s non levée%s (%s) : retenue de garantie à conserver par opposition motivée.', v_ouvertes,
                                 case when v_ouvertes > 1 then 's' else '' end, case when v_ouvertes > 1 then 's' else '' end, v_detail) end), 200),
    jsonb_build_object('projet', pr.id, 'reception_le', pr.reception_le, 'reserves_ouvertes', v_ouvertes, 'lien', private.lorani_lien_projet(pr.id)),
    case when v_depasse then format('gpa:%s:fin', pr.id) else format('gpa:%s:rappel:%s', pr.id, coalesce(v_rappel, 0)) end,
    true, private.lorani_chef_de_projet(pr.client_id, pr.id));
  return jsonb_build_object('projet', pr.id, 'genre', t.genre, 'reserves_ouvertes', v_ouvertes);
end $function$

fonction private.lorani_lectures_passage:
CREATE OR REPLACE FUNCTION private.lorani_lectures_passage()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  t public.travaux;
  r record;
  v_res jsonb;
  v_type text;
  n integer := 0;
  n_erreurs integer := 0;
  n_agences integer := 0;
  n_plu integer := 0;
begin
  for t in select * from private.prendre_travaux(array['lorani.piece_lue', 'lorani.reception', 'lorani.visa.rappel', 'lorani.visa.depasse',
                                                       'lorani.attestation.rappel', 'lorani.attestation.depasse', 'lorani.chantier.rappel', 'lorani.chantier.depasse'],
                                                 200, interval '10 minutes', 'lorani_lecture') loop
    begin
      v_type := null;
      if t.genre = 'lorani.piece_lue' then
        select x.type_piece into v_type from public.pieces x where x.id = (t.charge ->> 'piece')::uuid;
      end if;
      if t.genre = 'lorani.reception' then
        v_res := private.lorani_rattacher_reception((t.charge ->> 'reception')::bigint);
      elsif t.genre in ('lorani.visa.rappel', 'lorani.visa.depasse') then
        v_res := private.lorani_visa_rappeler(t);
      elsif t.genre in ('lorani.attestation.rappel', 'lorani.attestation.depasse') then
        v_res := private.lorani_attestation_rappeler(t);
      elsif t.genre in ('lorani.chantier.rappel', 'lorani.chantier.depasse') then
        v_res := private.lorani_chantier_rappeler(t);
      elsif v_type = 'lorani_situation_travaux' then
        v_res := private.lorani_poser_situation_lue((t.charge ->> 'piece')::uuid);
      elsif v_type = 'lorani_attestation_decennale' then
        v_res := private.lorani_poser_attestation_lue((t.charge ->> 'piece')::uuid);
      elsif v_type = 'lorani_offre' then
        v_res := private.lorani_poser_offre_lue((t.charge ->> 'piece')::uuid);
      elsif v_type in ('lorani_planche', 'lorani_cctp', 'lorani_dpgf', 'lorani_plu_reglement', 'lorani_metre', 'lorani_cerfa',
                           'lorani_attestation_re2020', 'lorani_plan_bet', 'lorani_notice')
            or exists (select 1 from public.lorani_controle_pieces cp where cp.piece_id = (t.charge ->> 'piece')::uuid) then
        v_res := private.lorani_piece_controle_lue((t.charge ->> 'piece')::uuid);
        if v_type = 'lorani_dpgf' then
          v_res := coalesce(v_res, '{}'::jsonb) || jsonb_build_object('consultations', private.lorani_offres_dpgf_lue((t.charge ->> 'piece')::uuid));
        end if;
      else
        v_res := private.lorani_lire_piece((t.charge ->> 'piece')::uuid);
      end if;
      perform private.finir_travail(t.id, v_res);
      n := n + 1;
    exception when others then
      perform private.echouer_travail(t.id, left(sqlstate || ' ' || sqlerrm, 2000));
      n_erreurs := n_erreurs + 1;
    end;
  end loop;
  -- Les recherches de PLU dont les réponses sont arrivées (ou qui ont attendu trop longtemps).
  for r in select l.projet_id from public.lorani_plu l where l.statut in ('geocodage', 'zonage') or l.complements_statut = 'en_cours' loop
    begin
      perform private.lorani_plu_avancer(r.projet_id);
      perform private.lorani_plu_complements_avancer(r.projet_id);
      n_plu := n_plu + 1;
    exception when others then
      n_erreurs := n_erreurs + 1;
    end;
  end loop;
  -- Le battement de chaque agence qui a des dossiers en cours, même à vide.
  for r in select distinct pr.client_id from public.lorani_projets pr where pr.actif loop
    perform private.battre(r.client_id, 'lorani_lecture', jsonb_build_object('passage', now()), interval '15 minutes');
    n_agences := n_agences + 1;
  end loop;
  return jsonb_build_object('pieces', n, 'erreurs', n_erreurs, 'agences', n_agences, 'plu', n_plu);
end $function$

fonction private.modifier_demande(uuid,t:
CREATE OR REPLACE FUNCTION private.modifier_demande(p_demande uuid, p_resume text DEFAULT NULL::text, p_montant numeric DEFAULT NULL::numeric, p_payload jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_d public.demandes_validation;
  v_resume text;
  v_montant numeric(14,2);
  v_payload jsonb;
  v_modifs jsonb := '[]'::jsonb;
  v_trace jsonb := '[]'::jsonb;
  v_cle text;
  v_nouvelle uuid;
begin
  if v_uid is null then
    raise exception 'Une modification est toujours faite par une personne connectée.' using errcode = '42501';
  end if;

  select * into v_d from public.demandes_validation where id = p_demande for update;
  if not found then
    raise exception 'Demande introuvable.' using errcode = 'P0002';
  end if;
  if not private.voit_objet_pour(v_uid, v_d.client_id, v_d.objet_type, v_d.objet_id)
     or not exists (select 1 from public.comptes c where c.user_id = v_uid and c.client_id = v_d.client_id) then
    raise exception 'Demande introuvable.' using errcode = 'P0002';
  end if;
  if v_d.statut <> 'en_attente' then
    raise exception 'Cette demande n''est plus en attente (%).', v_d.statut using errcode = '23514';
  end if;
  if v_d.demandeur_id = v_uid then
    raise exception 'Vous avez déposé cette demande : annulez-la et déposez-en une autre.' using errcode = '42501';
  end if;
  perform private.exiger_decideur(v_d, v_uid);

  v_resume := coalesce(nullif(btrim(p_resume), ''), v_d.resume);
  v_montant := coalesce(p_montant, v_d.montant);
  v_payload := v_d.payload || coalesce(p_payload, '{}'::jsonb);

  if v_resume is distinct from v_d.resume then
    v_modifs := v_modifs || jsonb_build_array(jsonb_build_object('champ', 'resume', 'avant', v_d.resume, 'apres', v_resume));
    v_trace := v_trace || jsonb_build_array(jsonb_build_object('champ', 'resume', 'avant', v_d.resume, 'apres', v_resume));
  end if;
  if v_montant is distinct from v_d.montant then
    v_modifs := v_modifs || jsonb_build_array(jsonb_build_object('champ', 'montant', 'avant', v_d.montant, 'apres', v_montant));
    v_trace := v_trace || jsonb_build_array(jsonb_build_object('champ', 'montant', 'avant', v_d.montant, 'apres', v_montant));
  end if;
  for v_cle in select jsonb_object_keys(coalesce(p_payload, '{}'::jsonb)) loop
    if (v_d.payload -> v_cle) is distinct from (v_payload -> v_cle) then
      v_modifs := v_modifs || jsonb_build_array(jsonb_build_object(
        'champ', 'payload.' || v_cle, 'avant', v_d.payload -> v_cle, 'apres', v_payload -> v_cle));
      v_trace := v_trace || jsonb_build_array(jsonb_build_object('champ', 'payload.' || v_cle));
    end if;
  end loop;
  if v_modifs = '[]'::jsonb then
    raise exception 'Aucune modification : la demande est identique.' using errcode = '22023';
  end if;

  insert into public.demandes_validation (
    client_id, entite_id, module, type_action, objet_type, objet_id, resume, montant, devise,
    payload, echeance, cle_idempotence)
  values (
    v_d.client_id, v_d.entite_id, v_d.module, v_d.type_action, v_d.objet_type, v_d.objet_id, v_resume, v_montant,
    v_d.devise, v_payload || jsonb_build_object('remplace', v_d.id, 'modifications', v_modifs),
    v_d.echeance, 'remplace:' || v_d.id::text)
  returning id into v_nouvelle;

  update public.demandes_validation set statut = 'annulee' where id = v_d.id;

  perform private.journaliser(
    v_d.client_id, 'demandes_validation.remplacement', 'demandes_validation', v_d.id::text,
    jsonb_build_object('nouvelle', v_nouvelle, 'modifications', v_trace), v_d.entite_id);
  return v_nouvelle;
end $function$

fonction private.tiroma_brancher_cabinet:
CREATE OR REPLACE FUNCTION private.tiroma_brancher_cabinet(p_client uuid, p_entite uuid, p_voie text DEFAULT 'exports'::text, p_libelle text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  k public.tiroma_cabinets; e public.entites; v_id uuid; v_jeux text[]; v_nom text;
begin
  perform private.tiroma_exiger_gerant(p_client, p_entite, 'branche');
  select * into k from public.tiroma_cabinets where client_id = p_client and entite_id = p_entite;
  if not found then
    raise exception 'Cabinet introuvable : installez-le d''abord (tiroma_installer_cabinet).' using errcode = 'P0002';
  end if;
  if k.statut = 'clos' then
    raise exception 'Ce cabinet est clos.' using errcode = '55000';
  end if;
  select * into e from public.entites where client_id = p_client and id = p_entite;
  if not exists (select 1 from public.modeles_jeux m where m.module = 'tiroma' and m.logiciel = k.logiciel) then
    raise exception 'Aucun modèle d''export pour le logiciel « % » : Tiroma ne lit pour l''instant que Logos_w.', k.logiciel
      using errcode = 'P0002';
  end if;
  v_nom := coalesce(p_libelle, case k.logiciel when 'logosw' then 'Logos_w' when 'julie' then 'Julie' when 'veasy' then 'Veasy'
                                               else initcap(k.logiciel) end || ' — ' || e.nom);
  v_id := private.brancher(p_client, 'tiroma', k.logiciel, p_voie, left(v_nom, 120), p_entite, e.fuseau, null);
  select array_agg(j.code order by private.tiroma_ordre_jeu(j.code)) into v_jeux
  from public.branchements_jeux j where j.branchement_id = v_id;
  update public.tiroma_cabinets set statut = 'actif' where id = k.id and statut in ('installation', 'coupe');
  perform private.journaliser_module(p_client, 'tiroma', 'tiroma.connecteur_active', 'tiroma_cabinets', k.id::text,
    jsonb_build_object('branchement', v_id, 'voie', p_voie, 'logiciel', k.logiciel, 'jeux', to_jsonb(v_jeux)), p_entite);
  perform private.battre(p_client, 'tiroma_releve', jsonb_build_object('branchement', v_id, 'etat', 'branche'), interval '3 days');
  return v_id;
end $function$

fonction private.tiroma_changer_mode(uui:
CREATE OR REPLACE FUNCTION private.tiroma_changer_mode(p_client uuid, p_entite uuid, p_mode text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_avant text; v_id uuid;
begin
  if (select auth.uid()) is null then
    if private.tiroma_role_session() not in ('service_role', 'postgres') then
      raise exception 'Seul le titulaire du cabinet, ou Omega, change son mode.' using errcode = '42501';
    end if;
  elsif not private.tiroma_est_titulaire(p_client, p_entite) then
    raise exception 'Seul le titulaire du cabinet, ou Omega, change son mode.' using errcode = '42501';
  end if;
  if p_mode is null or p_mode not in ('a_blanc', 'reel') then
    raise exception 'Le mode vaut a_blanc ou reel.' using errcode = '22023';
  end if;
  select k.mode, k.id into v_avant, v_id from public.tiroma_cabinets k
  where k.client_id = p_client and k.entite_id = p_entite for update;
  if not found then
    raise exception 'Cabinet introuvable.' using errcode = 'P0002';
  end if;
  if v_avant = p_mode then return; end if;
  update public.tiroma_cabinets set mode = p_mode, mode_depuis = now() where id = v_id;
end $function$

fonction private.tiroma_installer_cabine:
CREATE OR REPLACE FUNCTION private.tiroma_installer_cabinet(p_client uuid, p_entite uuid, p_logiciel text, p_perimetre text DEFAULT 'cabinet'::text, p_logiciel_version text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid; v_fuseau text; v_territoire text; v_fuseau_territoire text; v_complet boolean;
begin
  perform private.tiroma_exiger_gerant(p_client, p_entite, 'installe');
  select e.fuseau into v_fuseau from public.entites e where e.client_id = p_client and e.id = p_entite;
  if not found then
    raise exception 'Entité introuvable dans cette organisation.' using errcode = 'P0002';
  end if;
  v_territoire := private.territoire_de_entite(p_client, p_entite);
  if v_territoire is null then
    raise exception 'Le territoire du cabinet est inconnu : renseignez le code ISO de son entité (GP, FR-971, FR…).'
      using errcode = '22023', hint = 'Tiroma ne suppose jamais la métropole : les jours ouvrés en dépendent.';
  end if;
  select t.fuseau, t.complet into v_fuseau_territoire, v_complet from public.territoires t where t.code = v_territoire;
  if not coalesce(v_complet, false) then
    raise exception 'Les jours fériés de droit local de % ne sont pas au calendrier : Tiroma n''y calcule aucun jour ouvré.', v_territoire
      using errcode = '22023', hint = 'Relever d''abord ces jours dans le texte local (brique B5).';
  end if;
  if v_fuseau is distinct from v_fuseau_territoire then
    raise exception 'Le fuseau de l''entité (%) ne correspond pas à son territoire (%, %).', v_fuseau, v_territoire, v_fuseau_territoire
      using errcode = '22023', hint = '7 h à Pointe-à-Pitre n''est pas 7 h à Paris : le point du matin en dépend.';
  end if;
  insert into public.tiroma_cabinets (client_id, entite_id, logiciel, logiciel_version, perimetre_partage)
  values (p_client, p_entite, p_logiciel, p_logiciel_version, p_perimetre)
  returning id into v_id;
  insert into public.tiroma_regles (client_id, entite_id) values (p_client, p_entite);
  return v_id;
end $function$

fonction private.tracer():
CREATE OR REPLACE FUNCTION private.tracer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ligne jsonb;
  v_avant jsonb;
  v_client uuid;
  v_objet text;
  v_donnees jsonb;
  v_args text[] := coalesce(tg_argv::text[], array[]::text[]);
  v_inclus text[];
  v_exclus text[];
  v_cle text;
begin
  if coalesce(current_setting('omega.effacement_objet', true), '') = 'oui' then
    return null;
  end if;

  v_inclus := array(select substr(a, 2) from unnest(v_args) a where left(a, 1) = '+');
  v_exclus := array(select a from unnest(v_args) a where left(a, 1) <> '+');

  if tg_op = 'DELETE' then
    v_ligne := to_jsonb(old);
  else
    v_ligne := to_jsonb(new);
  end if;

  if tg_table_name = 'clients' then
    if tg_op = 'DELETE' then
      return null;
    end if;
    v_client := (v_ligne ->> 'id')::uuid;
  else
    v_client := (v_ligne ->> 'client_id')::uuid;
  end if;

  if v_client is null
     or v_client::text = coalesce(current_setting('omega.effacement_client', true), '') then
    return null;
  end if;

  v_objet := case tg_table_name
    when 'comptes' then v_ligne ->> 'user_id'
    when 'comptes_entites' then (v_ligne ->> 'user_id') || ':' || (v_ligne ->> 'entite_id')
    else v_ligne ->> 'id'
  end;

  if tg_op = 'UPDATE' then
    v_avant := to_jsonb(old);
    v_donnees := '{}'::jsonb;
    for v_cle in select jsonb_object_keys(v_ligne) loop
      if (cardinality(v_inclus) = 0 or v_cle = any (v_inclus))
         and not (v_cle = any (v_exclus))
         and (v_avant -> v_cle) is distinct from (v_ligne -> v_cle) then
        v_donnees := v_donnees || jsonb_build_object(v_cle, jsonb_build_array(v_avant -> v_cle, v_ligne -> v_cle));
      end if;
    end loop;
    if v_donnees = '{}'::jsonb then
      return null;
    end if;
  elsif cardinality(v_inclus) > 0 then
    select coalesce(jsonb_object_agg(e.cle, e.valeur), '{}'::jsonb) into v_donnees
    from jsonb_each(v_ligne) as e(cle, valeur)
    where e.cle = any (v_inclus);
  else
    v_donnees := v_ligne - v_exclus;
  end if;

  perform private.journaliser(
    v_client,
    tg_table_name || '.' || case tg_op when 'INSERT' then 'creation' when 'UPDATE' then 'modification' else 'suppression' end,
    tg_table_name,
    v_objet,
    v_donnees,
    case when tg_table_name = 'entites' then (v_ligne ->> 'id')::uuid
         else nullif(v_ligne ->> 'entite_id', '')::uuid end);
  return null;
end $function$

fonction public.f_audit_trail():
CREATE OR REPLACE FUNCTION public.f_audit_trail()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v_avant jsonb; v_apres jsonb; v_cle text;
begin
  if tg_op in ('UPDATE','DELETE') then v_avant := to_jsonb(old); end if;
  if tg_op in ('INSERT','UPDATE') then v_apres := to_jsonb(new); end if;
  v_cle := coalesce(v_apres->>'id', v_avant->>'id', v_apres->>'cle', v_avant->>'cle',
    (coalesce(v_apres->>'client_id', v_avant->>'client_id') || '/' || coalesce(v_apres->>'moteur', v_avant->>'moteur')));
  -- jamais de secret en clair dans l'audit
  if tg_table_name = 'parametres' and coalesce(v_apres->>'cle', v_avant->>'cle') ilike '%secret%' then
    if v_avant is not null then v_avant := jsonb_set(v_avant, '{valeur}', '"[EXPURGE]"'); end if;
    if v_apres is not null then v_apres := jsonb_set(v_apres, '{valeur}', '"[EXPURGE]"'); end if;
  end if;
  insert into public.audit_journal (table_cible, operation, cle_ligne, avant, apres)
  values (tg_table_name, tg_op, v_cle, v_avant, v_apres);
  return coalesce(new, old);
end $function$

fonction public.loc_refacturer_peages(uu:
CREATE OR REPLACE FUNCTION public.loc_refacturer_peages(p_contrat uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_client uuid := private.loc_client_de_la_personne(array['gerant', 'admin', 'valideur', 'collaborateur'], 'Les péages se refacturent par l''agence.');
  c public.loc_contrats;
  lp public.loc_bareme_lignes;
  lf public.loc_bareme_lignes;
  x public.loc_passages_peage;
  v_fuseau text;
  v_bareme uuid;
  v_version integer;
  v_prop uuid;
  v_rang integer := 0;
  v_n integer := 0;
  v_taux numeric;
  v_ht numeric;
begin
  select * into c from public.loc_contrats where client_id = v_client and id = p_contrat;
  if not found or not private.voit_entite(c.client_id, c.entite_id) then
    raise exception 'Contrat introuvable.' using errcode = 'P0002';
  end if;
  if not exists (select 1 from public.loc_passages_peage p where p.client_id = c.client_id and p.contrat_id = c.id and p.statut = 'paye' and p.refacture_proposition_id is null) then
    raise exception 'Aucun passage payé à refacturer sur ce contrat : payez d''abord les passages chez l''opérateur.' using errcode = '55000';
  end if;
  if exists (select 1 from public.loc_propositions p where p.client_id = c.client_id and p.contrat_id = c.id and p.statut in ('calculee', 'preuve_manquante', 'a_valider', 'validee')) then
    raise exception 'Une facture de ce contrat est en cours : refacturez les péages une fois émise.' using errcode = '55000';
  end if;
  select e.fuseau into v_fuseau from public.entites e where e.client_id = c.client_id and e.id = c.entite_id;
  v_bareme := private.loc_bareme_en_vigueur(c.client_id, (now() at time zone coalesce(v_fuseau, 'Europe/Paris'))::date);
  select * into lp from public.loc_bareme_lignes l where l.client_id = c.client_id and l.bareme_id = v_bareme and l.code = 'PEAGE' order by l.categorie_id nulls last limit 1;
  if lp.id is null then
    raise exception 'Ajoutez au barème la ligne PEAGE, unité « devis » (péage refacturé au montant réel, prévu par vos conditions générales).' using errcode = '23514';
  end if;
  select * into lf from public.loc_bareme_lignes l where l.client_id = c.client_id and l.bareme_id = v_bareme and l.code = 'FRAIS_PEAGE' order by l.categorie_id nulls last limit 1;
  select coalesce(max(p.version), 0) + 1 into v_version from public.loc_propositions p where p.client_id = c.client_id and p.contrat_id = c.id;
  insert into public.loc_propositions (client_id, entite_id, contrat_id, version, source, bareme_id, entrees, calculee_par)
  values (c.client_id, c.entite_id, c.id, v_version, 'saisie', v_bareme, jsonb_build_object('objet', 'peages'), (select auth.uid()))
  returning id into v_prop;
  for x in select * from public.loc_passages_peage p where p.client_id = c.client_id and p.contrat_id = c.id and p.statut = 'paye' and p.refacture_proposition_id is null order by p.passe_le loop
    v_rang := v_rang + 1;
    -- le péage payé est un montant toutes taxes : refacturé sur une ligne taxable, il est ramené hors taxes
    v_taux := private.loc_taux_tva(c.client_id, c.entite_id, lp.taux_tva);
    v_ht := case when lp.regime_tva = 'taxable' and coalesce(v_taux, 0) > 0 then round(x.montant_eur / (1 + v_taux / 100), 2) else x.montant_eur end;
    perform private.loc_poser_ligne(c.client_id, v_prop, v_rang, 'frais', lp.famille, lp.code,
      format('%s — %s, %s', lp.libelle, coalesce(x.portique, x.operateur), to_char(x.passe_le at time zone coalesce(v_fuseau, 'Europe/Paris'), 'DD/MM/YYYY à HH24:MI')),
      lp.id, 'forfait', 1, v_ht, v_ht, lp.regime_tva, v_taux, 'chiffree',
      jsonb_build_object('passage', x.id, 'operateur', x.operateur, 'reference', x.reference, 'paiement', x.paiement_reference),
      jsonb_build_array(jsonb_build_object('note', format('Passage %s chez %s, payé le %s (référence %s)', x.reference, x.operateur,
                                                          to_char(x.paye_le at time zone coalesce(v_fuseau, 'Europe/Paris'), 'DD/MM/YYYY'), x.paiement_reference))),
      false);
    if lf.id is not null and lf.prix_eur is not null then
      v_rang := v_rang + 1;
      perform private.loc_poser_ligne(c.client_id, v_prop, v_rang, 'frais', lf.famille, lf.code, lf.libelle || ' — passage ' || x.reference,
        lf.id, lf.unite, 1, lf.prix_eur, round(lf.prix_eur, 2), lf.regime_tva, private.loc_taux_tva(c.client_id, c.entite_id, lf.taux_tva), 'chiffree',
        jsonb_build_object('passage', x.id), '[]'::jsonb, false);
    end if;
    update public.loc_passages_peage set refacture_proposition_id = v_prop, statut = 'refacture' where id = x.id;
    v_n := v_n + 1;
  end loop;
  update public.loc_propositions p
     set statut = 'calculee',
         total_ht = (select coalesce(sum(l.montant_ht), 0) from public.loc_proposition_lignes l where l.proposition_id = v_prop),
         total_tva = (select coalesce(sum(l.montant_tva), 0) from public.loc_proposition_lignes l where l.proposition_id = v_prop),
         total_ttc = (select coalesce(sum(l.montant_ttc), 0) from public.loc_proposition_lignes l where l.proposition_id = v_prop),
         total_frais_ttc = (select coalesce(sum(l.montant_ttc), 0) from public.loc_proposition_lignes l where l.proposition_id = v_prop)
   where p.id = v_prop;
  perform private.deposer_travail(c.client_id, 'tavaro', 'tavaro.deposer_demande', jsonb_build_object('proposition', v_prop), 'tavaro:deposer:' || v_prop::text, 0::smallint);
  perform private.journaliser_module(c.client_id, 'tavaro', 'tavaro.peages_refactures', 'loc_contrats', c.id::text,
    jsonb_build_object('contrat', c.numero, 'passages', v_n, 'proposition', v_prop), c.entite_id);
  return jsonb_build_object('contrat', c.id, 'proposition', v_prop, 'passages', v_n);
end $function$
